const r = await tools.exec_command({cmd:"set -eu
jq -e '
  (.project == "Checkout recovery") and
  (.agent == "Codex") and
  (.duration.minutes == 18.5) and
  (.intervention.count == 2) and
  (.file.changed_count == 7) and
  (.test.passed == 14 and .test.total == 14) and
  (.deployment.status == "unknown") and
  (.evidence_count == 2) and
  (.evidence_digests | length == 2) and
  (.privacy == "summary-only")
' out/receipt.json >/dev/null
node - <<'NODE'
const fs = require('fs');
const crypto = require('crypto');
const manifestBytes = fs.readFileSync('run-manifest.json');
const manifest = JSON.parse(manifestBytes);
const receipt = JSON.parse(fs.readFileSync('out/receipt.json', 'utf8'));
const sha = data => crypto.createHash('sha256').update(data).digest('hex');
if (sha(manifestBytes) !== receipt.full_manifest_digest.digest) throw Error('full digest mismatch');
const expected = manifest.evidence.map(e => sha(JSON.stringify(e)));
const actual = receipt.evidence_digests.map(e => e.digest);
if (JSON.stringify(expected) !== JSON.stringify(actual)) throw Error('evidence digest mismatch');
for (const file of ['out/receipt.json', 'out/receipt.svg']) {
  const text = fs.readFileSync(file, 'utf8');
  for (const secret of ['/Users/', 'acme', 'ORCHID', 'Northwind', 'internal.example.invalid', '/run/91']) {
    if (text.includes(secret)) throw Error(`${secret} leaked in ${file}`);
  }
}
const svg = fs.readFileSync('out/receipt.svg', 'utf8');
if (!/<svg[^>]*width="1200"[^>]*height="675"/.test(svg)) throw Error('wrong SVG dimensions');
console.log('JSON, digests, dimensions, and privacy scan passed');
